    <div id="app"></div>

    <script>
      const imageData = {
        title: "Summer Editorial",
        description:
          "A high-resolution preview of your latest upload, ready for final review before publishing or removing from the library.",
        date: "May 6, 2026",
        size: "18.4 MB",
        resolution: "3840 x 2560",
        alt: "Beach shoreline with gentle waves and pastel sunset tones",
        src:
          "https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=1200&q=80",
      };

      const ImagePreview = ({ image }) => `
        <section class="preview-card" aria-labelledby="page-title">
          <div class="image-panel">
            <div class="image-frame">
              <img src="${image.src}" alt="${image.alt}" />
            </div>
            <div class="image-actions">
              <p id="delete-status" class="status-message" aria-live="polite"></p>
              <button type="button" class="button button-danger trigger" id="open-dialog">
                Delete image
              </button>
            </div>
          </div>

          <div class="details-panel">
            <div>
              <p class="meta-kicker">Image Library</p>
              <h1 id="page-title">${image.title}</h1>
            </div>
            <p>${image.description}</p>
            <div class="stats" aria-label="Image details">
              <div class="stat">
                <span class="stat-label">Uploaded</span>
                <span class="stat-value">${image.date}</span>
              </div>
              <div class="stat">
                <span class="stat-label">File size</span>
                <span class="stat-value">${image.size}</span>
              </div>
              <div class="stat">
                <span class="stat-label">Resolution</span>
                <span class="stat-value">${image.resolution}</span>
              </div>
              <div class="stat">
                <span class="stat-label">Status</span>
                <span class="stat-value">Ready to publish</span>
              </div>
            </div>
            <div class="button-row" aria-label="Secondary actions">
              <button type="button" class="button button-secondary">Download</button>
              <button type="button" class="button button-secondary">Share</button>
            </div>
          </div>
        </section>
      `;

      const DeleteDialog = () => `
        <dialog id="delete-dialog" aria-labelledby="dialog-title" aria-describedby="dialog-copy">
          <div class="dialog-panel">
            <h2 id="dialog-title" class="dialog-title">Delete this image?</h2>
            <p id="dialog-copy" class="dialog-copy">
              This will remove the image from your library. You can’t undo this action once the
              image has been deleted.
            </p>
            <div class="dialog-actions">
              <button type="button" class="button button-secondary" id="cancel-dialog">
                Keep image
